const originalOrder = new Map<string, number>();
for (const [gradeText, keys] of Object.entries(sequence)) {
  const grade = Number(gradeText);
  if (keys.length !== (grade === 6 ? 40 : 70)) throw new Error(`Неверная длина программы ${grade}`);
  keys.forEach((key, index) => {
    const id = grade === 3 ? `g3_m${Math.floor(index / 7) + 1}_l${index % 7 + 1}`
      : grade === 6 ? grade6Ids[index] : `g${grade}_l${grade === 7 ? String(index + 1).padStart(2, '0') : index + 1}`;
    topics.set(id, key);
    originalOrder.set(id, index);
  });
}

