function gridCommands(task: Task) {
  return (task.allowedCommands ?? []).map(code => {
    const key = code.replace(/^drone\./, '').replace(/[()_]/g, '').toLowerCase();
    const meaning = /^for /.test(code) ? 'повторение; вложенные команды пиши с отступом' : commandMeanings[key];
    if (!meaning) throw new Error(`Нет понятного описания команды ${task.id}: ${code}`);
    return { code, meaning };
  });
}

