export function reviseLessons(tasks: Task[]): Task[] {
  const revised = tasks.map(original => {
    // New courses carry authored, topic-specific guides; retain their scaffolds and order.
    if (original.courseId === 'course_grade8' && original.lesson) return original;
    const task = { ...original };
    const mappedKey = topicOverrides[task.id]?.[0] ?? topics.get(task.id);
    const key = task.type === 'wireframe_builder' ? 'wireframe' : task.type === 'ai_neuron' ? 'neuron' : task.type === 'spreadsheet' ? (task.spreadsheetConfig?.formulaType === 'if' ? 'ifformula' : task.spreadsheetConfig?.formulaType === 'multiply' ? 'multiply' : 'spreadsheet') : mappedKey;
    const card = cards[key ?? ''];
    if (!card) throw new Error(`Нет методической карточки: ${task.id}, ${key}`);
    const [concept, originalExplanation, example, reflection] = card;
    const explanation = CLEAR_EXPLANATIONS[key!] ?? originalExplanation;
    task.title = titles[task.id] ?? (task.type === 'quiz' ? QUIZ_TITLES[task.id] ?? concept : cleanLessonTitle(task.title)).replace(/Экзамен модуля:\s*/i, 'Проверяем себя: ');
    task.module = units.find(([, keys]) => keys.includes(topicOverrides[task.id]?.[1] ?? (key === 'wireframe' ? 'design' : key === 'neuron' ? 'ai' : key) ?? ''))?.[0] ?? task.module;
    if (task.sortingConfig) task.sortingConfig = { ...task.sortingConfig, algorithm: 'bubble' };
    if (task.spreadsheetConfig?.formulaType === 'sum') task.spreadsheetConfig = { ...task.spreadsheetConfig, targetFormula: '=SUM(D2:D4)' };
    if (['g7_l19', 'g7_l20', 'g7_l22', 'g7_l23', 'g7_l24', 'g7_l59', 'g7_l70'].includes(task.id)) task.module = 'Циклы, функции и проекты Python';
    let [goal, steps, success] = practical[task.type] ?? ['Выполни задание по образцу.', ['Прочитай условие.', 'Выполни и проверь результат.'], 'Результат соответствует условию.'];
    if (task.type === 'quiz') {
      if (!QUIZ_TITLES[task.id]) throw new Error(`Нет цели проверочного задания: ${task.id}`);
      goal = `Проверь, как ты понимаешь тему «${QUIZ_TITLES[task.id]}».`;
    }
    if (task.type === 'spreadsheet') {
      const isIf = task.spreadsheetConfig?.formulaType === 'if';
      goal = isIf ? 'Заполни результат по условию в таблице.' : task.id === 'g3_m8_l1' ? 'Вычисли стоимость: цена × количество.' : 'Вычисли общий итог строк D2–D4.';
      steps = ['Найди нужные ячейки и их значения.', 'Введи формулу, начиная со знака =.', 'Сравни результат с расчётом вручную.'];
      success = 'Формула использует нужные ячейки и даёт правильный результат.';
    }
    if (task.type === 'binary_switches' || task.type === 'binary_bulbs') {
      goal = 'Собери числа включёнными лампочками.';
      steps = ['Прочитай число и веса лампочек.', 'Включи нужные веса и сложи их.', 'Проверь результат каждого раунда.'];
      success = 'Сумма включённых весов совпадает с числом задания.';
    }
    if (task.type === 'circuit_builder' || task.type === 'circuit') {
      const gates = task.circuitConfig?.gates ?? [task.circuitConfig?.gate ?? task.circuitConfig?.targetGate ?? 'and'];
      goal = `Проверь логическое правило ${gates.map(g => g.toUpperCase()).join(', ')}.`;
      steps = ['Прочитай правило текущей схемы.', 'Сравни выход для разных пар входов.', 'Настрой входы для указанного результата.'];
      success = 'Выход схемы соответствует требуемому результату.';
    }
    let workedExample = example;
    let starterCode: string | undefined;
    if (task.type === 'terminal') {
      goal = terminalGoals[task.id] ?? goal;
      const gap = gaps[task.id];
      if (gap) {
        if (!task.initialCode?.includes(gap[0])) throw new Error(`Пропуск не найден: ${task.id}`);
        starterCode = task.initialCode.replace(gap[0], gap[1]);
        steps = ['Прочитай данные и найди место для дополнения в шаблоне.', 'Дополни выражение или команду по условию.', 'Запусти и сравни результат с условием.'];
      } else starterCode = /^(SELECT|CREATE)/i.test(task.initialCode ?? '') ? '-- Напиши запрос по условию задания' : '# Введи команды по условию задания';
    }
    if (task.type === 'grid') {
      starterCode = task.id === 'g4_l43' ? task.initialCode : '# Составь маршрут: одна команда на строке\n';
      if (task.id === 'g4_l43') goal = 'Найди и исправь ошибку в готовом маршруте. Робот должен дойти до цели.';
      workedExample += ' В начале робот смотрит вправо. ' + gridCommands(task).slice(0, 3).map(({code, meaning}) => `${code} — ${meaning}`).join('. ') + '.';
      if (/for |repeat/i.test(task.initialCode ?? '')) workedExample += '\nПример двух повторов:\nfor i in range(2):\n    forward()\nПробелы перед forward() показывают тело цикла.';
    }
    if (task.type === 'html') {
      if (task.id === 'g7_l34') task.htmlConfig = { ...task.htmlConfig, targetTag: 'button' };
      if (key === 'css') workedExample += ' Например: <p style="color: navy;">Текст</p>. Стиль записан внутри открывающего тега.';
      starterCode = '<main>\n  <!-- Добавь элемент по условию -->\n</main>';
      goal = `Создай элемент <${task.htmlConfig?.targetTag ?? 'p'}>.` + (task.htmlConfig?.targetStyle ? ` Условие оформления: ${task.htmlConfig.targetStyle}` : '');
    }
    if (task.type === 'spreadsheet') task.title = task.spreadsheetConfig?.formulaType === 'if' ? 'Условие в таблице' : task.spreadsheetConfig?.formulaType === 'multiply' ? 'Цена × количество' : 'Сумма по строкам';
    if (task.type === 'grid') task.title = key === 'debug' ? 'Находим ошибку в маршруте' : /for |repeat/i.test(task.initialCode ?? '') ? 'Маршрут с повторением' : 'Маршрут по клеткам';
    if (task.type === 'wireframe_builder') task.title = 'Собираем понятный экран';
    if (task.type === 'network_route') task.title = 'Выбираем маршрут данных';
    if (task.type === 'sorting') task.title = 'Сортируем соседние числа';
    if (task.type === 'tree_search') task.title = 'Ищем число в дереве';
    if (task.type === 'ai_neuron') {
      workedExample = 'Модель умножает признаки на веса, складывает результаты и добавляет смещение. Например, при признаках 1 и 0, весах 2 и 1, смещении −1 получаем 1 × 2 + 0 × 1 − 1 = 1. Сумма больше нуля — класс 1; иначе — класс 0. Это учебная модель.';
    }
    task.lesson = { topic: key, concept, explanation, example: workedExample, goal, steps: [...steps], success, reflection, starterCode, commands: task.type === 'grid' ? gridCommands(task) : undefined };
    // Короткое описание рассказывает о действии, а не перечисляет стандарты.
    task.description = goal;
    const safe = (text: string) => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    task.theory = `<h2>${safe(concept)}</h2><p>${safe(explanation)}</p><h3>Пример</h3><p>${safe(workedExample)}</p>`;
    return task;
  });
  // Сначала основания, затем применение. Внутри раздела сохраняется авторский порядок.
  const rank = (task: Task) => {
    const index = units.findIndex(([name]) => name === task.module);
    if (task.courseId === 'course_grade7') {
      const order = [2, 3, 1, 6, 5, 4, 8, 0, 7];
      return order.indexOf(index);
    }
    return index;
  };
  return revised.sort((a, b) => a.courseId.localeCompare(b.courseId) || rank(a) - rank(b) || (originalOrder.get(a.id) ?? 0) - (originalOrder.get(b.id) ?? 0));
}
